import React from 'react';
import { Canvas } from '@react-three/fiber';
import { EffectComposer } from '@react-three/postprocessing';
import { Fluid } from '@whatisjery/react-fluid-distortion';


const customColors = ['#FF0000']; // White, Yellow, Red
 // Add your custom colors here

const config = {
    fluidColor: '#FF0000', //Sets the main color of the fluid effect.
    backgroundColor: '#070410', //Defines the background color behind the fluid effect.
    showBackground: false,
    blend: 3, // Increase blend for more blending effect
    intensity: 0.7, // Increase intensity for stronger effect
    force: 2, // Increase force for more dispersion
    distortion: 1, // Adjust distortion for a lighter effect
    radius: 0.3, // Increase radius for larger effect area
    curl: 7,
    swirl: 6,
    velocityDissipation: 0.99, //Reduces the fluid velocity over time.
    densitionDissipation: 0.90, //Reduces the fluid density over time.
    pressure: 0.80, //Controls the reduction of pressure in the fluid simulation.
    rainbow: false, //Boolean to activate color mode based on mouse direction.
    colors: customColors, // Use custom colors
    dissipation: 1,
  };

const SwirlCursor = () => {

  return (
    <>
      <Canvas
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          height: '100vh',
          width: '100vw',
          zIndex:9999,
          pointerEvents: 'none',
        }}>
        <EffectComposer>
          <Fluid {...config} />
        </EffectComposer>
      </Canvas>
     
    </>
  );
};

export default SwirlCursor;
