function Experience() {
  useEffect(() => {
    const handleScroll = () => {
      const timelineItems = document.querySelectorAll('.timeline-item');
      timelineItems.forEach((item) => {
        const rect = item.getBoundingClientRect();
        if (rect.top < window.innerHeight && rect.bottom >= 0) {
          item.classList.add('visible');
        } else {
          item.classList.remove('visible');
        }
      });
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <Container className="experience-section">
      <h1 className="experience-title">Work Experience</h1>
      <div className="timeline">
        {experiences.map((exp, index) => (
          <Row key={index} className="timeline-item">
            <Col md={6} className={index % 2 === 0 ? "timeline-content left" : "timeline-content right"}>
              <h2>{exp.title}</h2>
              <h5>{exp.company} - {exp.period}</h5>
              <div>{exp.description}</div>
            </Col>
            <Col md={6} className={index % 2 === 0 ? "timeline-marker left" : "timeline-marker right"}>
            </Col>
          </Row>
        ))}
      </div>
    </Container>
  );
}

export default Experience;
